/// Scans the next token, if any.
fn scan(&mut self) -> Result<Option<Token>> {
    self.skip_whitespace();
    if self.chars.peek().is_none() {
        return Ok(None);
    }
    if let Some(t) = self.scan_ident_quoted()? {
        return Ok(Some(t));
    }
    if let Some(t) = self.scan_ident_or_keyword() {
        return Ok(Some(t));
    }
    if let Some(t) = self.scan_number() {
        return Ok(Some(t));
    }
    if let Some(t) = self.scan_string()? {
        return Ok(Some(t));
    }
    if let Some(t) = self.scan_symbol() {
        return Ok(Some(t));
    }
    Err(errinput!("unexpected character"))
}
